// Command docscan2 reports run-together Go doc comments: one contiguous
// comment block that describes more than one declaration, which happens when
// a declaration is inserted between an existing comment and the function it
// documented, or when the documented function is moved away.
//
// Two shapes, both reported:
//
//	A. The block's FIRST line names a declaration other than the one it is
//	   attached to — the intruder inherited someone else's doc.
//	B. A LATER line in the block opens by naming another declaration — a
//	   second description is buried inside the first, and the declaration it
//	   describes is left with no doc of its own.
//
// A name counts only if it is declared somewhere in the same package, so an
// ordinary sentence that happens to start with a capitalized word is not
// flagged.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var leadName = regexp.MustCompile(`^([A-Za-z_]\w*) `)

func main() {
	n := 0
	for _, root := range os.Args[1:] {
		dirs, err := packageDirs(root)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(2)
		}
		for _, dir := range dirs {
			hits, err := scanDir(dir)
			if err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(2)
			}
			for _, h := range hits {
				fmt.Println(h)
			}
			n += len(hits)
		}
	}
	fmt.Printf("%d run-together doc comment(s)\n", n)
}

// packageDirs returns every directory under root holding .go files, skipping
// scratch and sibling-checkout trees that are not part of the tracked source.
func packageDirs(root string) ([]string, error) {
	seen := map[string]bool{}
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			switch info.Name() {
			case ".tmp", ".worktrees", ".git", "node_modules", ".venv":
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(path, ".go") {
			seen[filepath.Dir(path)] = true
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("walking %s: %w", root, err)
	}
	dirs := make([]string, 0, len(seen))
	for d := range seen {
		dirs = append(dirs, d)
	}
	return dirs, nil
}

func scanDir(dir string) ([]string, error) {
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dir, nil, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parsing %s: %w", dir, err)
	}
	var hits []string
	for _, pkg := range pkgs {
		declared := map[string]bool{}
		for _, f := range pkg.Files {
			for _, d := range f.Decls {
				if name, _ := declDoc(d); name != "" {
					declared[name] = true
				}
			}
		}
		for _, f := range pkg.Files {
			for _, d := range f.Decls {
				name, doc := declDoc(d)
				if name == "" || doc == nil {
					continue
				}
				lines := strings.Split(strings.TrimSpace(doc.Text()), "\n")
				for i, line := range lines {
					m := leadName.FindStringSubmatch(line)
					if m == nil || m[1] == name || !declared[m[1]] {
						continue
					}
					// Shape B needs the line to start a sentence, not
					// continue one: the previous line must be blank or the
					// block must have ended a sentence.
					if i > 0 && !endsSentence(lines[i-1]) {
						continue
					}
					shape := "B (a second description buried inside)"
					if i == 0 {
						shape = "A (inherited another declaration's doc)"
					}
					hits = append(hits, fmt.Sprintf("%s: %q shape %s — line %d describes %q",
						fset.Position(doc.Pos()), name, shape, i+1, m[1]))
				}
			}
		}
	}
	return hits, nil
}

func endsSentence(s string) bool {
	s = strings.TrimSpace(s)
	return s == "" || strings.HasSuffix(s, ".") || strings.HasSuffix(s, ":")
}

func declDoc(d ast.Decl) (string, *ast.CommentGroup) {
	switch v := d.(type) {
	case *ast.FuncDecl:
		return v.Name.Name, v.Doc
	case *ast.GenDecl:
		if len(v.Specs) != 1 {
			return "", nil
		}
		switch s := v.Specs[0].(type) {
		case *ast.TypeSpec:
			return s.Name.Name, v.Doc
		case *ast.ValueSpec:
			if len(s.Names) == 1 {
				return s.Names[0].Name, v.Doc
			}
		}
	}
	return "", nil
}

// Command docscan3 reports run-together Go doc comments.
//
// The defect: one contiguous comment block describes two declarations, so Go
// attaches the whole block to whichever declaration follows it and the other
// declaration is left with no doc at all. It happens when a declaration is
// inserted between an existing comment and the function it documented.
//
// The signature is deliberately narrow, because "a comment mentions another
// function" is ordinary, correct prose and not a defect. Both halves must
// hold:
//
//  1. Declaration D has NO doc comment of its own, and
//  2. some other doc comment block in the same file contains a line that
//     opens a sentence with D's own name.
//
// Requiring (1) is what makes this precise: a block that merely references
// another function in passing does not orphan it, because that function still
// has its own doc.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

func main() {
	n := 0
	for _, root := range os.Args[1:] {
		hits, err := scan(root)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(2)
		}
		for _, h := range hits {
			fmt.Println(h)
		}
		n += len(hits)
	}
	fmt.Printf("%d orphaned doc comment(s)\n", n)
}

func scan(root string) ([]string, error) {
	fset := token.NewFileSet()
	var hits []string
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			switch info.Name() {
			case ".tmp", ".worktrees", ".git", "node_modules", ".venv":
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return fmt.Errorf("parsing %s: %w", path, err)
		}
		// Every doc block in the file, with the declaration it is attached to.
		type block struct {
			owner string
			pos   token.Pos
			lines []string
		}
		var blocks []block
		var undocumented []string
		for _, d := range f.Decls {
			name, doc := declDoc(d)
			if name == "" {
				continue
			}
			if doc == nil {
				undocumented = append(undocumented, name)
				continue
			}
			blocks = append(blocks, block{name, doc.Pos(), strings.Split(strings.TrimSpace(doc.Text()), "\n")})
		}
		for _, orphan := range undocumented {
			open := regexp.MustCompile(`^` + regexp.QuoteMeta(orphan) + ` `)
			for _, b := range blocks {
				if b.owner == orphan {
					continue
				}
				for i, line := range b.lines {
					if !open.MatchString(line) {
						continue
					}
					if i > 0 && !endsSentence(b.lines[i-1]) {
						continue
					}
					hits = append(hits, fmt.Sprintf(
						"%s: doc block on %q, line %d, describes %q — which has no doc of its own",
						fset.Position(b.pos), b.owner, i+1, orphan))
				}
			}
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("walking %s: %w", root, err)
	}
	return hits, nil
}

func endsSentence(s string) bool {
	s = strings.TrimSpace(s)
	return s == "" || strings.HasSuffix(s, ".") || strings.HasSuffix(s, ":")
}

func declDoc(d ast.Decl) (string, *ast.CommentGroup) {
	switch v := d.(type) {
	case *ast.FuncDecl:
		return v.Name.Name, v.Doc
	case *ast.GenDecl:
		if len(v.Specs) != 1 {
			return "", nil
		}
		switch s := v.Specs[0].(type) {
		case *ast.TypeSpec:
			return s.Name.Name, v.Doc
		case *ast.ValueSpec:
			if len(s.Names) == 1 {
				return s.Names[0].Name, v.Doc
			}
		}
	}
	return "", nil
}

